-- A data-modifying WITH query is a CTE InitPlan of the main statement's top
-- node, whatever the main statement is (SELECT, set operation, INSERT), and
-- the main statement reads it by CTE Scan. Columns of its write print
-- qualified, as the statement's range table holds more than one relation.
-- A simple INSERT source, star or not, is pulled up into the INSERT.
CREATE TABLE m593 (id int, v int);
CREATE TABLE n593 (id int, v int);
EXPLAIN (COSTS OFF) WITH w AS (INSERT INTO m593 VALUES (1, 2) RETURNING *) SELECT * FROM w;
EXPLAIN (COSTS OFF) WITH w AS (DELETE FROM m593 RETURNING id) SELECT count(*) FROM w;
EXPLAIN (COSTS OFF) WITH w AS (INSERT INTO m593 VALUES (1, 2) RETURNING *) SELECT 1;
EXPLAIN (COSTS OFF) WITH w AS (DELETE FROM m593 RETURNING *) INSERT INTO m593 SELECT * FROM w;
EXPLAIN (COSTS OFF) WITH w AS (INSERT INTO m593 VALUES (1, 2) RETURNING *) SELECT * FROM w UNION ALL SELECT * FROM w;
EXPLAIN (COSTS OFF) WITH w AS MATERIALIZED (SELECT * FROM n593) INSERT INTO m593 SELECT * FROM w;
EXPLAIN (COSTS OFF) INSERT INTO m593 SELECT * FROM n593;
EXPLAIN (VERBOSE, COSTS OFF) WITH w AS (INSERT INTO m593 VALUES (1, 2) RETURNING *) SELECT * FROM w;
EXPLAIN (VERBOSE, COSTS OFF) WITH w AS (UPDATE m593 SET v = 3 RETURNING id) SELECT * FROM w;
EXPLAIN (VERBOSE, COSTS OFF) WITH w AS (DELETE FROM m593 RETURNING *) SELECT * FROM w;
EXPLAIN (VERBOSE, COSTS OFF) UPDATE m593 SET v = 3 RETURNING id;
WITH w AS (INSERT INTO m593 VALUES (1, 2), (3, 4) RETURNING *) INSERT INTO n593 SELECT * FROM w;
SELECT * FROM n593 ORDER BY id;
